            { id: 'AS_twinofheart', name: 'Twin of heart', type: 'Vital', subtypes: ['Human', 'Mage'], limit: 1, hp: 8, cost: 0, burn: 0, set: 'N. All Stars', image: '(AS) TwinOfHeart.jpg', description: 'Withstand. This card can make up to 2 actions per turn. when you flip this card up at the start of the game you can place 1 "Twin of Soul" from outside the game onto your side of the field. If "Twin of Soul" you control leaves the field: this card can make an additional action each turn and any healing it outputs is doubled Heart Release (0)- Gain 1 gold or heal all cards you control 2' },
            { id: 'AS_twinofsoul', name: 'Twin of Soul', type: 'Vital', subtypes: ['Human', 'Mage'], limit: 1, hp: 8, cost: 0, burn: 0, set: 'N. All Stars', image: '(AS) TwinOfSoul.jpg', description: 'Withstand. This card can make up to 2 actions per turn. If "Twin of Heart" you control leaves the field: this card can make an additional action each turn, gains 2 strength markers and Withstand. Prepare (0)- Gain 1 gold Soul Release (1)- (single) Deal 2 dmg' }
